const submitRequiredFields = [
    ["applicant_email_address", "Applicant Email Address"],
    ["applicant_phone_number", "Applicant Phone Number"],
    ["applicant_name", "Full Name"],
    ["custom_tin_number", "TIN Number"],
    ["address_line_1", "Address Line 1"],
    ["custom_province", "Province"],
    ["custom_new_city", "City"],
    ["country", "Country"],
    ["loan_product", "Loan Product"],
    ["loan_amount", "Loan Amount"],
    ["repayment_method", "Repayment Method"],
    ["repayment_periods", "Repayment Period in Months"],
