const monthlyFactor = (frequency) => ({
    "Weekly": 52 / 12,
    "Fortnightly": 26 / 12,
    "Bi-monthly": 2,
    "Monthly": 1
}[frequency] || 1);

const money = (value) => window.comfort_hp_math.round(Number(value || 0));
