async function refreshAddressDropdowns() {
    const request = async (fieldname, level, parent) => {
        const field = frappe.web_form.fields_dict[fieldname];
        if (!field) return;
        const sequence = (field.__flexiLocationSequence || 0) + 1;
        field.__flexiLocationSequence = sequence;
        const response = await frappe.call({method:"comfort_homes.hp_lending.hp_intake.locations",args:{level,parent}});
        if (field.__flexiLocationSequence !== sequence) return;
        if (typeof field.set_data !== "function") throw new Error("Native address control is unavailable; contact staff.");
        field.set_data(response.message || []);
        field.__flexiLocationRows = response.message || [];
    };
    await Promise.all([
        request("custom_province","Province",null),
        request("custom_new_city","City",frappe.web_form.get_value("custom_province")),
        request("custom_suburb","Suburb",frappe.web_form.get_value("custom_new_city"))
    ]);
}

