/* comfort_homes: loan application employment period */
(function () {
	function updateEmploymentPeriod() {
		const startDate = frappe.web_form.get_value("custom_flexi_employment_start_date");
		if (!startDate) {
			frappe.web_form.set_value("custom_flexi_employment_period", "");
			return;
		}
		const start = new Date(`${startDate}T00:00:00`);
		const now = new Date();
		if (Number.isNaN(start.getTime()) || start > now) return;
		let months = (now.getFullYear() - start.getFullYear()) * 12 + now.getMonth() - start.getMonth();
		if (now.getDate() < start.getDate()) months -= 1;
		months = Math.max(months, 0);
		const years = Math.floor(months / 12);
		const remainder = months % 12;
		const period = `${years} ${years === 1 ? "year" : "years"}${remainder ? ` ${remainder} ${remainder === 1 ? "month" : "months"}` : ""}`;
		frappe.web_form.set_value("custom_flexi_employment_period", period);
	}

	frappe.web_form.on("custom_flexi_employment_start_date", updateEmploymentPeriod);
	frappe.web_form.events.on("after_load", updateEmploymentPeriod);
})();

/* comfort_homes: loan application live calculation refresh v7 */
(function () {
	let refreshTimer;
	let depositSource;
	const purchaseTable = "custom_flexi_purchase_items";
	const incomeTables = new Set([
		"custom_flexi_income_entries", "custom_flexi_living_expenses", "custom_flexi_finance_obligations"
	]);
	const financeFields = new Set([
		"custom_flexi_deposit_amount", "custom_flexi_deposit_percent", "custom_flexi_surcharge_rate",
		"custom_flexi_documentation_fee", "custom_flexi_admin_fee_rate", "custom_flexi_stamp_duty_fee",
		"custom_flexi_other_fee", "custom_flexi_term_months", "custom_flexi_interest_rate",
		"custom_flexi_payment_period", "custom_flexi_selected_dsr", "loan_product"
	]);
	const number = (value) => {
		const parsed = Number(String(value ?? "").replace(/[^0-9.-]/g, ""));
		return Number.isFinite(parsed) ? parsed : 0;
	};
	const money = (value) => window.comfort_hp_math.round(number(value));

	function tableFor(target) {
		return [purchaseTable, ...incomeTables].find((fieldname) =>
			target?.closest?.(`[data-fieldname="${fieldname}"]`)
		);
	}

	function setChildValue(row, fieldname, value) {
		if (money(row[fieldname]) === money(value)) return;
		row[fieldname] = value;
		if (row.doctype && row.name) frappe.model.set_value(row.doctype, row.name, fieldname, value);
	}

	function monthlyFactor(frequency) {
		return ({ Weekly: 52 / 12, Fortnightly: 26 / 12, "Bi-monthly": 2, Monthly: 1 })[frequency] || 1;
	}

	function renderDtiMatrix(income, obligations) {
		const field = frappe.web_form?.fields_dict?.custom_flexi_dti_matrix;
		if (!field?.$wrapper) return;
		const periods = [["Weekly", 12 / 52], ["Fortnightly", 12 / 26], ["Bi-Monthly", 1 / 2], ["Monthly", 1]];
		const currency = (value) => `FJD ${money(value).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
		const rows = [
			["Income Used for DTI", income],
			["Current Obligations", obligations],
			["Income After Current Obligations", income - obligations],
			["Pre-Application DTI", income ? obligations / income * 100 : 0, true],
		];
		const heading = periods.map(([label]) => `<th>${label}</th>`).join("");
		const body = rows.map(([label, monthly, isPercent]) => {
			const cells = periods.map(([, factor]) => {
				const value = isPercent ? monthly : monthly * factor;
				return `<td>${isPercent ? `${money(value).toFixed(2)}%` : currency(value)}</td>`;
			}).join("");
			return `<tr><th>${label}</th>${cells}</tr>`;
		}).join("");
		field.$wrapper.html(`<div class="flexi-summary-table"><h3>Pre-Application DTI (Debt to Income Ratio)</h3><div class="table-responsive"><table><thead><tr><th>Assessment</th>${heading}</tr></thead><tbody>${body}</tbody></table></div></div>`);
	}

	function currentDtiAssessment() {
		const form = frappe.web_form;
		const income = (form.get_value("custom_flexi_income_entries") || []).reduce((total, row) => {
			const monthly = number(row.amount) * monthlyFactor(row.frequency);
			return total + (row.income_type === "Salary Deductions" ? Math.abs(monthly) : monthly);
		}, 0);
		const obligations = (form.get_value("custom_flexi_finance_obligations") || []).reduce((total, row) =>
			total + number(row.amount) * monthlyFactor(row.frequency), 0);
		return { income: money(income), obligations: money(obligations) };
	}

	function renderCurrentDtiMatrix() {
		if (!frappe.web_form) return;
		const assessment = currentDtiAssessment();
		renderDtiMatrix(assessment.income, assessment.obligations);
	}

	function calculateIncomeAndExpensesSafely() {
		const form = frappe.web_form;
		const incomeRows = form.get_value("custom_flexi_income_entries") || [];
		const expenseRows = form.get_value("custom_flexi_living_expenses") || [];
		const obligationRows = form.get_value("custom_flexi_finance_obligations") || [];
		const income = incomeRows.reduce((sum, row) => {
			const monthly = number(row.amount) * monthlyFactor(row.frequency);
			setChildValue(row, "monthly_amount", money(monthly));
			return sum + (row.income_type === "Salary Deductions" ? Math.abs(monthly) : monthly);
		}, 0);
		const expenses = expenseRows.reduce((sum, row) => {
			const monthly = number(row.expense_amount) * number(row.frequency_per_month || 1);
			setChildValue(row, "monthly_amount", money(monthly));
			return sum + monthly;
		}, 0);
		const obligations = obligationRows.reduce((sum, row) => {
			const monthly = number(row.amount) * monthlyFactor(row.frequency);
			setChildValue(row, "monthly_amount", money(monthly));
			return sum + monthly;
		}, 0);
		const set = (fieldname, value) => form.set_value(fieldname, money(value));
		set("custom_flexi_total_monthly_income", income);
		set("custom_flexi_total_annual_income", income * 12);
		set("custom_flexi_total_monthly_expenses", expenses);
		set("custom_flexi_net_monthly_income", income - expenses);
		set("custom_flexi_dsr_total_income", income);
		set("custom_flexi_total_finance_obligations", obligations);
		set("custom_flexi_dsr_net_income", income - obligations);
		const maxDsr = number(form.get_value("custom_flexi_selected_dsr")) || 35;
		const preDsr = income ? money(obligations / income * 100) : 0;
		set("custom_flexi_pre_dsr", preDsr);
		set("custom_flexi_dsr_margin", Math.max(maxDsr - preDsr, 0));
		set("custom_flexi_weekly_eligibility", Math.max((income * maxDsr / 100 - obligations) / window.comfort_hp_math.profile(window.comfort_hp_math.readWeb(form)).weeks, 0));
		renderDtiMatrix(income, obligations);
		["custom_flexi_income_entries", "custom_flexi_living_expenses", "custom_flexi_finance_obligations"].forEach((fieldname) => {
			form.fields_dict[fieldname]?.grid?.refresh?.();
			form.fields_dict[fieldname]?.refresh?.();
		});
		return { income, obligations };
	}

	function sourceForDeposit() {
		if (depositSource) return depositSource;
		const amount = number(frappe.web_form.get_value("custom_flexi_deposit_amount"));
		const percent = number(frappe.web_form.get_value("custom_flexi_deposit_percent"));
		return !amount && percent ? "percent" : "amount";
	}

	function recalculate(kind) {
		if (!frappe.web_form) return;
		if (kind === "income") {
			const assessment = calculateIncomeAndExpensesSafely();
			calculateFinanceSummary(sourceForDeposit(), assessment);
			return;
		}
		if (kind === "purchase") {
			const rows = frappe.web_form.get_value(purchaseTable) || [];
			const purchaseValue = rows.reduce((total, row) => {
				const lineTotal = money(number(row.quantity) * number(row.unit_price));
				setChildValue(row, "total_amount", lineTotal);
				return total + lineTotal;
			}, 0);
			frappe.web_form.set_value("custom_flexi_cash_price", money(purchaseValue));
			frappe.web_form.fields_dict[purchaseTable]?.refresh?.();
		}
		calculateFinanceSummary(sourceForDeposit());
	}

	function queue(kind) {
		window.clearTimeout(refreshTimer);
		// Grid controls finish updating their row a little after the browser event.
		refreshTimer = window.setTimeout(() => recalculate(kind), 450);
	}

	/*
	 * The original Web Form script receives the browser's formatted value
	 * (for example "FJD 9,000.00") and used Number(value), which evaluates to
	 * NaN.  Replace just its table listener before after_load calls it.  This
	 * keeps the existing form layout/default rows while storing finite numbers.
	 */
	bindTableCalculations = function () {
		const tableColumns = {
			custom_flexi_income_entries: ["income_type", "description", "frequency", "amount"],
			custom_flexi_living_expenses: ["category", "description", "frequency_per_month", "expense_amount"],
			custom_flexi_finance_obligations: ["obligation_type", "provider", "payment_method", "frequency", "amount"],
			custom_flexi_purchase_items: ["product_description", "quantity", "unit_price"],
		};
		Object.entries(tableColumns).forEach(([fieldname, columns]) => {
			const field = frappe.web_form?.fields_dict?.[fieldname];
			if (!field?.wrapper || field.wrapper.dataset.comfortHomesSafeTableListener) return;
			field.wrapper.dataset.comfortHomesSafeTableListener = "1";
			let timer;
			$(field.wrapper)
				.off("input.flexiTotals change.flexiTotals")
				.off(".comfortHomesSafeTotals")
				.on("input.comfortHomesSafeTotals change.comfortHomesSafeTotals", "input, select", (event) => {
					const column = event.target?.dataset?.fieldname;
					if (!columns.includes(column)) return;
					const index = Number(event.target.closest(".grid-row")?.dataset?.idx) - 1;
					const row = field.grid?.get_data()?.[index];
					if (row) {
						row[column] = ["amount", "expense_amount", "unit_price", "quantity", "frequency_per_month"].includes(column)
							? number(event.target.value)
							: event.target.value;
					}
					window.clearTimeout(timer);
					timer = window.setTimeout(() => {
						recalculate(fieldname === purchaseTable ? "purchase" : "income");
					}, 150);
				});
		});
	};

	// Rows added after the page loads can bypass the grid listener entirely.
	// Capture numeric edits before Frappe's legacy bubble listener can assign
	// Number("FJD 9,000.00") to the child row.
	function captureFormattedGridAmount(event) {
		const target = event.target;
		const table = tableFor(target);
		const fieldname = target?.dataset?.fieldname;
		const numericColumns = new Set(["amount", "expense_amount", "unit_price", "quantity", "frequency_per_month"]);
		if (!table || !numericColumns.has(fieldname)) return;
		const field = frappe.web_form?.fields_dict?.[table];
		const index = Number(target.closest(".grid-row")?.dataset?.idx) - 1;
		const row = field?.grid?.get_data()?.[index];
		if (!row) return;
		event.stopImmediatePropagation();
		row[fieldname] = number(target.value);
		queue(table === purchaseTable ? "purchase" : "income");
	}
	document.addEventListener("input", captureFormattedGridAmount, true);
	document.addEventListener("change", captureFormattedGridAmount, true);

	function onChanged(event) {
		const fieldname = event.target?.closest?.("[data-fieldname]")?.dataset?.fieldname;
		const table = tableFor(event.target);
		if (table === purchaseTable) {
			// Remember the initial 10% (or other configured) deposit before the
			// older table listener has a chance to reset it to zero on an empty row.
			depositSource = depositSource || sourceForDeposit();
			return queue("purchase");
		}
		if (incomeTables.has(table)) return queue("income");
		if (!financeFields.has(fieldname)) return;
		if (fieldname === "custom_flexi_deposit_percent") depositSource = "percent";
		if (fieldname === "custom_flexi_deposit_amount") depositSource = "amount";
		queue("finance");
	}

	document.addEventListener("input", onChanged, true);
	document.addEventListener("change", onChanged, true);
	// Preserve a configured default percentage (for example 10%) before a
	// newly-added blank item row causes the legacy table listener to reset it.
	window.setTimeout(() => {
		if (!depositSource) depositSource = sourceForDeposit();
		renderCurrentDtiMatrix();
	}, 0);
	frappe.web_form?.events?.on?.("after_load", () => window.setTimeout(renderCurrentDtiMatrix, 0));
	// An old customer-maintained page handler still draws this HTML field when
	// the DTI step is opened. Render last and calculate directly from the rows.
	document.addEventListener("click", (event) => {
		if (!event.target?.closest?.(".slide-step")?.textContent?.includes("DTI")) return;
		window.setTimeout(renderCurrentDtiMatrix, 250);
		window.setTimeout(renderCurrentDtiMatrix, 900);
	}, true);
})();

/* comfort_homes: unified submit coordinator dev9 */
/* One submit owner. Uses native save/confirmation, never recursive button.click(). */
(() => {
    if (window.__flexiSubmitCoordinatorLoaded) return;
    window.__flexiSubmitCoordinatorLoaded = true;
    const accept = "frappe.website.doctype.web_form.web_form.accept";
    let phase = "idle", revision = 0, timer, currentForm;
    const text = v => String(v ?? "").trim();
    const numeric = v => Number(String(v ?? "").replace(/[^0-9.-]/g, ""));
    const fail = message => { throw new Error(message); };
    function notice(message) {
        frappe.msgprint({title: __("Application submission"), message: __(message), indicator: "orange"});
    }
    // A visible, non-blocking progress message so a click is never met with silence.
    function progress(message) {
        if (typeof frappe.show_alert === "function") frappe.show_alert({message: __(message), indicator: "blue"}, 6);
        else notice(message);
    }
    // Never disable the button (a disabled button swallows clicks silently): mark it busy and
    // let submit() answer every click with a visible message instead.
    function status(value) {
        phase = value;
        const busy = ["checking", "saving"].includes(value);
        document.querySelectorAll(".submit-btn").forEach(b => {
            b.disabled = false;
            b.removeAttribute("disabled");
            b.setAttribute("aria-busy", busy ? "true" : "false");
            b.classList.toggle("flexi-busy", busy);
        });
    }
    function withTimeout(promise, ms, message) {
        let timeout;
        return Promise.race([
            Promise.resolve(promise),
            new Promise((_resolve, reject) => { timeout = window.setTimeout(() => reject(new Error(message)), ms); })
        ]).finally(() => window.clearTimeout(timeout));
    }
    function rows(form, name) { return form.fields_dict[name]?.grid?.get_data() || form.get_value(name) || []; }
    function replaceRows(form, name, values) {
        const control = form.fields_dict[name], grid = control?.grid;
        if (!grid) return;
        values.forEach((row, i) => { row.idx = i + 1; });
        // Frappe Grid.get_data(): frm.doc wins over df.data. Keep row identity.
        if (grid.frm) grid.frm.doc[grid.df.fieldname] = values;
        else grid.df.data = values;
        control.df.data = values;
        grid.refresh();
    }
    function cleanup(form) {
        const tables = {
            custom_flexi_purchase_items: r => text(r.product_description) || numeric(r.unit_price) !== 0,
            custom_flexi_application_contacts: r => [r.full_name,r.mobile_number,r.home_phone,r.employer_contact].some(text),
            custom_flexi_income_entries: r => numeric(r.amount) !== 0 || text(r.description),
            custom_flexi_living_expenses: r => numeric(r.expense_amount) !== 0 || text(r.description),
            custom_flexi_finance_obligations: r => numeric(r.amount) !== 0 || text(r.provider) || text(r.description),
            documents: r => text(r.file) || text(r.description)
        };
        for (const [name, meaningful] of Object.entries(tables)) {
            if (!form.fields_dict[name]) continue;
            const metadata = new Set(["doctype","name","idx","parent","parentfield","parenttype","owner","creation","modified","modified_by","docstatus","__islocal","__unsaved","monthly_amount","total_amount","income_type","category","obligation_type","frequency","frequency_per_month","quantity","document_type","contact_type","status"]);
            const all = rows(form, name), kept = all.filter(r => meaningful(r) || Object.entries(r).some(([key,value]) => !metadata.has(key) && (typeof value === "number" ? value !== 0 : Boolean(text(value)))));
            if (name === "custom_flexi_purchase_items") kept.forEach(r => {
                if (!text(r.product_description) || !Number.isFinite(numeric(r.quantity)) || numeric(r.quantity) <= 0 ||
                    !Number.isFinite(numeric(r.unit_price)) || numeric(r.unit_price) < 0) fail("Complete each purchase row; zero-priced goods are allowed.");
            });
            if (name === "documents") kept.forEach(r => {
                if (!text(r.file) || !text(r.document_type)) fail("Complete the document type and attachment on each entered document row.");
            });
            if (kept.length !== all.length) replaceRows(form, name, kept);
        }
    }
    async function prepare(form) {
        document.activeElement?.blur?.();
        await new Promise(resolve => window.setTimeout(resolve, 0));
        if (Object.values(form.fields_dict).some(f => f.uploading || f.file_upload?.uploading))
            fail("Wait for all attachments to finish uploading before submitting.");
        cleanup(form);
        if (typeof normalizeFijiPhoneFields === "function") normalizeFijiPhoneFields();
        if (typeof syncStandardAddressFields === "function") await syncStandardAddressFields();
        if (typeof calculateIncomeAndExpenses === "function") calculateIncomeAndExpenses();
        if (typeof calculateFinanceSummary === "function") calculateFinanceSummary();
        if (typeof flexiValidateFinalFields !== "function") fail("Application validation did not initialise. Keep this page open and contact staff; do not refresh your entered application.");
        flexiValidateFinalFields();
    }
    async function submit(form) {
        if (!["idle", "rejected"].includes(phase)) {
            if (phase === "uncertain") notice("The previous save result is uncertain. Keep your data here and ask staff to check whether it saved before retrying.");
            else if (phase === "saved") notice("This application has already been sent. Do not submit it again. If you cannot see a confirmation, ask staff to check.");
            else progress("Your application is still being checked and sent. Please wait.");
            return false;
        }
        status("checking");
        progress("Checking your application…");
        try {
            await withTimeout(prepare(form), 20000, "Checking your application took too long. Nothing was sent; please try again.");
            const value = key => text(form.get_value(key));
            const identity = [value("custom_tin_number"),value("applicant_email_address")];
            const checkedRevision = revision;
            const response = await withTimeout(
                frappe.call({method:"comfort_homes.api.check_existing_customer", args:{tin_number:identity[0],email:identity[1]}}),
                20000, "Could not verify duplicate details in time. Your application has not been sent; please try again.");
            if (!response || response.exc || !response.message || typeof response.message.exists === "undefined") fail("Could not verify duplicate details. Your application has not been sent; please retry.");
            if (checkedRevision !== revision || identity[0] !== value("custom_tin_number") || identity[1] !== value("applicant_email_address"))
                fail("Your application changed during validation. Review it and submit again.");
            if (response.message.exists) fail("A matching customer or co-applicant already exists. Please contact staff; no new application was sent.");
            flexiValidateFinalFields();
            if (window.saving) fail("A previous save is still in progress. Please wait a moment and try again.");
            status("saving");
            progress("Sending your application…");
            // Native save returns false both on early validation failure and after starting XHR.
            form.__flexiNativeSave.call(form);
            if (phase === "saving" && !window.saving) {
                status("rejected");
                notice("No save request started. Correct the validation errors shown above and retry; your entries remain here.");
            } else if (phase === "saving") {
                timer = window.setTimeout(() => {
                    if (phase === "saving") { status("uncertain"); notice("The save response is taking too long. Do not submit again. Keep this page open while staff check whether the application saved."); }
                }, 60000);
            }
        } catch (error) {
            window.clearTimeout(timer);
            const alreadyShown = error?.message === "Complete the required fields before submitting."; // validator listed them itself
            if (phase !== "saving" || !window.saving) {
                // No save request is in flight, so nothing was sent and a retry is safe.
                status("rejected");
                if (!alreadyShown) notice(error?.message || "Validation failed. Your entries are retained; please retry.");
            } else { status("uncertain"); notice("A save error occurred. Staff must check whether it saved before retrying. Keep this page open."); }
        }
        return false;
    }
    function isAccept(settings) {
        if ((settings?.url || "").includes(accept)) return true;
        const data = settings?.data;
        return (typeof data === "string" ? new URLSearchParams(data).get("cmd") : data?.cmd) === accept;
    }
    function install() {
        const form = window.frappe?.web_form;
        if (!location.pathname.startsWith("/loan-application") || !form?.save || form.__flexiNativeSave) return;
        currentForm = form;
        form.__flexiNativeSave = form.save;
        form.save = () => { void submit(form); return false; };
        const nativeSuccess = form.handle_success;
        form.handle_success = function(data) {
            window.clearTimeout(timer); status("saved");
            try { return nativeSuccess.call(this, data); }
            catch (_error) { notice("The application saved, but its confirmation could not display. Ask staff to open the saved application; do not submit again."); }
        };
        // Scoped observation only: never replace frappe.call or native request callbacks.
        $(document).on("ajaxComplete.flexiSubmit", (_event, xhr, settings) => {
            if (!isAccept(settings) || !["saving", "uncertain"].includes(phase)) return;
            window.clearTimeout(timer);
            if (xhr.responseJSON?.message?.name && !xhr.responseJSON?.exc) {
                status("saved");
                notice("The server returned a saved application. If confirmation is missing, ask staff to open it; do not submit again.");
            } else if (xhr.status >= 400 && xhr.status < 500 && xhr.status !== 408) {
                status("rejected"); notice("The server rejected this application. Correct the displayed error and retry; your entries remain here.");
            } else {
                status("uncertain"); notice("The save result is uncertain. Keep your entries and ask staff to check saved applications before any retry.");
            }
        });
    }
    // Capture on the form, before the native jQuery submit handler (also covers Enter).
    document.addEventListener("submit", event => {
        if (!event.target?.matches?.(".web-form") || !location.pathname.startsWith("/loan-application")) return;
        event.preventDefault(); event.stopImmediatePropagation();
        install();
        if (currentForm) void submit(currentForm);
        else notice("The form is not ready. Keep your data here and contact staff.");
    }, true);
    document.addEventListener("input", () => { revision += 1; }, true);
    document.addEventListener("change", () => { revision += 1; }, true);
    function ready() {
        if (!location.pathname.startsWith("/loan-application")) return;
        if (!window.frappe?.web_form?.events) { window.setTimeout(ready, 150); return; }
        frappe.web_form.events.on("after_load", install);
        install();
    }
    // Expose pure helpers for executable regression tests; no persistence or API bypass.
    window.flexiSubmit = {cleanup, replaceRows, submit, phase:() => phase};
    ready();
})();

